39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.BulkSignupWarning;
41	import org.springframework.samples.petclinic.service.CityCapacity;
42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.samples.petclinic.service.CustomerCodeGenerator;
44	import org.springframework.samples.petclinic.service.DailyRegistrationLimit;
45	import org.springframework.samples.petclinic.service.HouseholdMatcher;
46	import org.springframework.samples.petclinic.service.IdentityKey;
